package com.ozonehis.ozonectl;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The resolved plan: what runs, the ordered compose chain, the db-init
 * list and the pre-computed restore invocation. Pure data; generated by
 * the Resolver and consumed by the CLI and the manifest writer.
 */
final class Plan {

    final List<String> apps = new ArrayList<String>();
    final List<String> integrations = new ArrayList<String>();
    final Map<String, Boolean> modes = new LinkedHashMap<String, Boolean>();

    /** the ordered -f chain for `run` */
    final List<String> chain = new ArrayList<String>();
    /** feeds DB_INIT_LIST */
    final List<String> dbInit = new ArrayList<String>();

    /** extra -f files appended when restore is invoked */
    final List<String> restoreCompose = new ArrayList<String>();
    /** restore gate profiles activated when restore is invoked */
    final List<String> restoreProfiles = new ArrayList<String>();

    /** pre-computed ad-hoc chain per invocable mode (`up &lt;mode&gt;`) */
    final Map<String, List<String>> modeChains = new LinkedHashMap<String, List<String>>();

    boolean ssoEnabled() {
        Boolean enabled = modes.get("sso");
        return enabled != null && enabled;
    }
}
